    "Evidenzpakete sind signierte Exporte aus Audit-Log und kryptografischem Inventar. Sie zeigen, was trstctl beweisen kann und was Ihre Organisation weiterhin attestieren muss; sie sind Evidenz, keine Zertifizierung.",
