  "source.a.service.job.agent.or.workload.identity.t.dcc4188b56":
    "Eine Service-, Job-, Agenten- oder Workload-Identität, der kurzlebige Zugangsdaten ausgestellt werden können, anstatt statische Secrets zu speichern.",
